    const n = arr.length;
    for (let i = 0; i < n; i++)
        for (let j = i + 1; j < n; j++) {
            [arr[i], arr[j]] = [arr[j], arr[i]];
            if (cmp(arr, best) < 0) best = arr.slice();
            [arr[i], arr[j]] = [arr[j], arr[i]];
        }
    return best;
};

